def total_coverage(spans):
    if not spans:
        return 0

    spans.sort(key=lambda x: x[0])
    total = 0
    current_end = spans[0][1]

    for start, end in spans[1:]:
        if start > current_end:
            total += current_end - start + 1
            current_end = end
        elif end > current_end:
            current_end = end

    return total + current_end - spans[-1][0] + 1

